"""A production-board placeholder in a fictional workshop."""

def handle(request):
    """
    Builds a production board from the supplied request.

    The board groups queued and in_progress jobs by worker. Jobs with a missing,
    null or empty worker are grouped under the worker name 'Unassigned'.
    The resulting structure is:

        {'columns': [
            {'worker': <name>, 'jobs': [
                {'id': <id>, 'status': <status>},
                ...
            ]},
            ...
        ]}

    Columns are sorted lexicographically by worker name.
    Jobs within each column are sorted lexicographically by job id.
    Jobs with status 'done' or 'cancelled' are omitted.
    An empty input or a request without jobs results in no columns.
    """
    jobs = request.get('jobs', [])

    # Filter relevant jobs
    relevant = [
        job for job in jobs
        if job.get('status') in ('queued', 'in_progress')
    ]

    # If no relevant jobs, return empty columns
    if not relevant:
        return {'columns': []}

    # Group by worker, normalising missing/empty workers to 'Unassigned'
    groups = {}
    for job in relevant:
        worker = job.get('worker')
        if not worker:
            worker = 'Unassigned'
        groups.setdefault(worker, []).append(job)

    # Sort worker names lexicographically
    sorted_workers = sorted(groups.keys())

    columns = []
    for worker in sorted_workers:
        # Sort jobs by id lexicographically
        sorted_jobs = sorted(
            groups[worker],
            key=lambda j: j.get('id', '')
        )
        columns.append({
            'worker': worker,
            'jobs': [{'id': j['id'], 'status': j['status']} for j in sorted_jobs]
        })

    return {'columns': columns}
```

